  [["Größe", "Wurm 15 bis 25 cm lang"], ["Wo zu finden", "überall im Sandwatt"], ["Spur", "Kothaufen an einem Ende, Trichter am anderen"]],
  [["Wie lebt der Wattwurm?", "Er frisst Sand und verdaut die winzigen Lebewesen darin. Den sauberen Sand schiebt er als Häufchen nach oben."],
   ["Bedeutung", "Wattwürmer graben das Watt ständig um und versorgen es mit Sauerstoff."],
   ["Gut zu wissen", "Ein einziger Wattwurm wälzt im Jahr etwa 25 Kilogramm Sand um."]],
